using System.Text;

namespace Invoicing;

/// <summary>Renders an invoice to a plain-text document.</summary>
public sealed class InvoiceRenderer
{
    public string Render(Invoice invoice, Account account)
    {
        var builder = new StringBuilder();
        AppendHeader(builder, invoice.Number, account);

        decimal net = 0m;
        decimal vat = 0m;
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount < 0m)
            {
                continue;
            }

            net += line.NetAmount;
            vat += AppendInvoiceLine(
                builder,
                line.Description,
                line.NetAmount,
                line.VatRate);
        }

        var discount = CalculateDiscount(net, account.Kind);
        var gross = decimal.Max(0m, net + vat - discount);
        builder.AppendLine($"NET {net} VAT {vat} DISC {discount} TOTAL {gross}");
        AppendPaymentTerms(builder, account.Kind);

        return builder.ToString();
    }

    private static void AppendHeader(
        StringBuilder builder,
        string invoiceNumber,
        Account account)
    {
        builder.AppendLine($"INVOICE {invoiceNumber}");
        if (account.Name.Length > 0)
        {
            builder.AppendLine(account.Name);
        }

        switch (account.Kind)
        {
            case AccountKind.Business:
                builder.AppendLine("VAT registered");
                break;
            case AccountKind.Government:
                builder.AppendLine("Government purchase order");
                break;
            case AccountKind.Consumer:
                builder.AppendLine("Consumer");
                break;
        }
    }

    private static decimal AppendInvoiceLine(
        StringBuilder builder,
        string description,
        decimal netAmount,
        decimal vatRate)
    {
        var lineVat = netAmount * vatRate;
        if (vatRate == 0m)
        {
            builder.AppendLine($"{description} {netAmount} (zero-rated)");
        }
        else if (vatRate >= 0.2m)
        {
            builder.AppendLine($"{description} {netAmount} (std {lineVat})");
        }
        else
        {
            builder.AppendLine($"{description} {netAmount} (reduced {lineVat})");
        }

        if (description.Length > 40)
        {
            builder.AppendLine("  (description truncated)");
        }

        return lineVat;
    }

    private static decimal CalculateDiscount(decimal net, AccountKind accountKind)
    {
        if (net > 1000m && accountKind == AccountKind.Business)
        {
            return net * 0.05m;
        }

        return net > 5000m ? net * 0.10m : 0m;
    }

    private static void AppendPaymentTerms(StringBuilder builder, AccountKind accountKind)
    {
        builder.AppendLine(accountKind == AccountKind.Government
            ? "Remit within 30 days"
            : "Remit within 14 days");
    }
}
